            if (is.null(problem))
                problem <- message
        }
        if (!is.null(problem)) {
            stop("Invalid ", locations[[name]], " parameter ", name, ": ", problem, call. = FALSE)
        }
    }
    invisible(NULL)
}
form_value <- function (value, schema, validate, allow_empty = TRUE)
{
