            if (is.object(x) || !is.null(dim(x)) || !is.null(names(x)) || length(x) != 1L || anyNA(x) || !typeof(x) %in% c("character", "logical", "integer", "double") || (is.numeric(x) && !is.finite(x))) {
                stop("Free-form form fields must be finite scalar strings, numbers or booleans: ", name)
            }
        }
        if (is.null(value[[name]])) {
            stop("Null form fields have no unambiguous encoding: ", name)
        }
        if (identical(field$type, "array") && !length(value[[name]])) {
            stop("Empty form arrays have no unambiguous encoding: ", name)
        }
        type <- if (identical(field$type, "array"))
            field$items
        else field
        if (identical(type$format, "binary")) {
            parts <- if (identical(field$type, "array")) {
                value[[name]]
            }
            else {
                list(value[[name]])
            }
            if (!is.list(parts) || !is.null(names(parts)) || !length(parts) || !all(vapply(parts, function(x) is.raw(x) || inherits(x, "form_file"), logical(1)))) {
                stop("Binary form fields must be raw vectors or curl::form_file() values")
            }
            original[name] <- value[name]
            value[name] <- list(if (identical(field$type, "array")) rep(list(""), length(parts)) else "")
        }
    }
    value <- tryCatch(validate(value, schema), error = function(e) {
        stop("Invalid body: ", conditionMessage(e), call. = FALSE)
    })
